PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE `calculations` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`project_name` text NOT NULL,
	`section_name` text NOT NULL,
	`section_length` integer NOT NULL,
	`quantity` integer NOT NULL,
	`material_cost` real NOT NULL,
	`labor_cost` real NOT NULL,
	`utility_cost` real NOT NULL,
	`unit_cost` real NOT NULL,
	`total_cost` real NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `assignment_history` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`project_name` text NOT NULL,
	`scope` text NOT NULL,
	`element_key` text DEFAULT '' NOT NULL,
	`responsible` text NOT NULL,
	`previous_responsible` text DEFAULT '' NOT NULL,
	`changed_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `workspace_records` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`category` text NOT NULL,
	`project_key` text DEFAULT '' NOT NULL,
	`entity_key` text DEFAULT '' NOT NULL,
	`payload_json` text NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX workspace_records_lookup_idx ON workspace_records(category, project_key, entity_key, created_at);
CREATE INDEX assignment_project_idx ON assignment_history(project_name, changed_at);
